538→                };
539→
540→                let answer = ui.prompt(&prompt)?;
541→                if answer.as_string() != "yes" {
542→                    if step.skippable {
543→                        ui.message(&format!(
544→                            "    {}",
545→                            theme.format_skipped("Skipped (declined sensitive step)")
546→                        ));
547→                        results.push(StepResult::skipped(
548→                            &step.name,
549→                            crate::steps::CheckResult::complete("User declined sensitive step"),
550→                        ));
551→                        continue;
552→                    } else {
553→                        return Err(BivvyError::StepExecutionError {
554→                            step: step_name.clone(),
555→                            message: format!(
556→                                "Step '{}' is sensitive and not skippable, but user declined",
557→                                step.title
558→                            ),
559→                        });
560→                    }
561→                }
562→                had_prompt = true;
563→            }
564→
565→            // Blank line before spinner when a prompt was shown (visual spacing)
566→            if had_prompt {
567→                ui.message("");
568→            }
569→
570→            // Build step context for pattern matching
571→            let step_ctx = StepContext {
572→                name: step_name,
573→                command: &step.command,
574→                requires: &step.requires,
575→                template: None,
576→            };
577→
578→            let mut retry_count: u32 = 0;
579→            let mut skipped_by_user = false;
580→            #[allow(unused_assignments)]
581→            let mut final_result: Option<StepResult> = None;
582→
583→            // Outer loop: step execution (retry/fix re-enter here)
584→            'step_execution: loop {
585→                // Fresh spinner per attempt
586→                let attempt_label = if retry_count > 0 {
587→                    format!(
588→                        "Running `{}`... (attempt {}/{})",
589→                        step.command,
590→                        retry_count + 1,
591→                        step.retry + 1
592→                    )
593→                } else {
594→                    format!("Running `{}`...", step.command)
595→                };
596→                let mut spinner = ui.start_spinner_indented(&attempt_label, 4);
597→
598→                // Create live output callback:
599→                // - Interactive mode: spinner-based ring buffer (3 lines verbose, 2 normal)
600→                // - Non-interactive verbose: print all output directly to stdout
601→                let output_mode = ui.output_mode();
602→                let output_callback = spinner
603→                    .progress_bar()
604→                    .and_then(|bar| {
605→                        let max_lines = match output_mode {
606→                            OutputMode::Verbose => 3,
607→                            OutputMode::Normal => 2,
608→                            _ => return None,
609→                        };
610→                        Some(live_output_callback(
611→                            bar,
612→                            attempt_label.clone(),
613→                            6,
614→                            max_lines,
615→                        ))
616→                    })
617→                    .or_else(|| {
618→                        // Non-interactive verbose: stream output directly
619→                        if output_mode == OutputMode::Verbose {
620→                            let cb: crate::shell::OutputCallback = Box::new(|line: OutputLine| {
621→                                let text = match &line {
622→                                    OutputLine::Stdout(s) => s.trim_end(),
623→                                    OutputLine::Stderr(s) => s.trim_end(),
624→                                };
625→                                if !text.is_empty() {
626→                                    println!("      {text}");
627→                                }
628→                            });
629→                            Some(cb)
630→                        } else {
631→                            None
632→                        }
633→                    });
634→
635→                let exec_options = ExecutionOptions {
636→                    force: needs_force,
637→                    dry_run: options.dry_run,
638→                    capture_output: output_callback.is_none(),
639→                    ..Default::default()
640→                };
641→
642→                let step_start = Instant::now();
643→                let result = match execute_step(
644→                    step,
645→                    project_root,
646→                    context,
647→                    global_env,
648→                    &exec_options,
649→                    output_callback,
650→                ) {
651→                    Ok(result) => result,
652→                    Err(e) => {
653→                        warn!("Step '{}' errored: {}", step_name, e);
654→                        StepResult::failure(step_name, step_start.elapsed(), e.to_string(), None)
655→                    }
656→                };
657→
658→                let duration_str = format_duration(result.duration);
659→
660→                match result.status() {
661→                    StepStatus::Completed => {
662→                        let detail = if retry_count > 0 {
663→                            Some(format!("succeeded on retry (attempt {})", retry_count + 1))
664→                        } else {
665→                            None
666→                        };
667→                        spinner.finish_success(&format!("{} ({})", step_name, duration_str));
668→                        let mut r = result;
669→                        r.recovery_detail = detail;
670→                        final_result = Some(r);
671→                        break 'step_execution;
672→                    }
673→                    StepStatus::Skipped => {
674→                        spinner.finish_skipped("Skipped");
675→                        final_result = Some(result);
676→                        break 'step_execution;
677→                    }
678→                    StepStatus::Failed => {
679→                        spinner.finish_error(&format!("Failed ({})", duration_str));
680→
681→                        // Build combined error output for pattern matching and display
682→                        let mut output_parts = Vec::new();
683→                        if let Some(ref err) = result.error {
684→                            output_parts.push(err.as_str());
685→                        }
686→                        if let Some(ref output) = result.output {
687→                            let trimmed = output.trim();
688→                            if !trimmed.is_empty() {
689→                                output_parts.push(trimmed);
690→                            }
691→                        }
692→                        let combined_output = output_parts.join("\n");
693→
694→                        // Match against pattern registry
695→                        let fix = patterns::find_fix(&combined_output, &step_ctx);
696→                        let hint = patterns::find_hint(&combined_output, &step_ctx);
697→
698→                        // Show error block — skip in non-interactive verbose
699→                        // where output was already streamed to stdout
700→                        let output_was_streamed =
701→                            !ui.is_interactive() && output_mode == OutputMode::Verbose;
702→                        if !output_was_streamed {
703→                            ui.show_error_block(&step.command, &combined_output, hint.as_deref());
704→                        }
705→
706→                        // allow_failure: record and move on, no recovery menu
707→                        if step.allow_failure {
708→                            final_result = Some(result);
709→                            break 'step_execution;
710→                        }
711→
712→                        // Auto-retry before showing recovery menu
713→                        if retry_count < step.retry {
714→                            retry_count += 1;
715→                            ui.message(&format!(
716→                                "    Retrying... (attempt {}/{})",
717→                                retry_count + 1,
718→                                step.retry + 1
719→                            ));
720→                            continue 'step_execution;
721→                        }
722→
723→                        // Non-interactive: no recovery menu
724→                        if !interactive {
725→                            final_result = Some(result);
726→                            break 'step_execution;
727→                        }
728→
729→                        // Safety: cap total attempts to prevent infinite loops
730→                        // (e.g., in tests where MockUI defaults to "retry")
731→                        if retry_count >= MAX_STEP_ATTEMPTS {
732→                            warn!(
733→                                "Step '{}' exceeded max recovery attempts ({})",
734→                                step_name, MAX_STEP_ATTEMPTS
735→                            );
736→                            final_result = Some(result);
737→                            break 'step_execution;
738→                        }
739→
740→                        // Interactive recovery menu
741→                        let has_hint = hint.is_some();
742→                        'recovery_menu: loop {
743→                            let action =
744→                                recovery::prompt_recovery(ui, step_name, fix.as_ref(), has_hint)?;
745→
746→                            match action {
747→                                RecoveryAction::Retry => {
748→                                    retry_count += 1;
749→                                    continue 'step_execution;

  1→//! Interactive recovery for step failures.
  2→//!
  3→//! When a step fails during `bivvy run`, this module provides a recovery menu
  4→//! allowing the user to retry, fix, skip, open a debug shell, enter a custom
  5→//! fix command, or abort.
  6→
  7→use std::collections::HashMap;
  8→use std::path::Path;
  9→
 10→use crate::error::Result;
 11→use crate::shell::{execute, CommandOptions};
 12→use crate::ui::{Prompt, PromptOption, PromptType, UserInterface};
 13→
 14→use super::patterns::FixSuggestion;
 15→
 16→/// Recovery action chosen by the user.
 17→#[derive(Debug, Clone, PartialEq, Eq)]
 18→pub enum RecoveryAction {
 19→    /// Re-execute the step.
 20→    Retry,
 21→    /// Run the suggested fix command, then re-execute.
 22→    Fix(String),
 23→    /// Run a user-entered custom fix command, then re-execute.
 24→    CustomFix(String),
 25→    /// Skip this step and continue.
 26→    Skip,
 27→    /// Open a debug shell, then return to the recovery menu.
 28→    Shell,
 29→    /// Stop the workflow.
 30→    Abort,
 31→}
 32→
 33→/// Prompt the user for a recovery action after a step failure.
 34→///
 35→/// Returns the chosen action. The `fix` parameter controls whether a Fix
 36→/// option appears in the menu. The `has_hint` flag indicates a low-confidence
 37→/// match exists, which adds a "Fix (custom)" option for the user to enter
 38→/// their own command.
 39→pub fn prompt_recovery(
 40→    ui: &mut dyn UserInterface,
 41→    step_name: &str,
 42→    fix: Option<&FixSuggestion>,
 43→    has_hint: bool,
 44→) -> Result<RecoveryAction> {
 45→    let mut options = vec![PromptOption {
 46→        label: "Retry".to_string(),
 47→        value: "retry".to_string(),
 48→    }];
 49→
 50→    if let Some(f) = fix {
 51→        options.push(PromptOption {
 52→            label: format!("Fix — {}", f.label),
 53→            value: "fix".to_string(),
 54→        });
 55→    }
 56→
 57→    if has_hint {
 58→        options.push(PromptOption {
 59→            label: "Fix (custom) — enter your own command".to_string(),
 60→            value: "custom_fix".to_string(),
 61→        });
 62→    }
 63→
 64→    options.push(PromptOption {
 65→        label: "Skip".to_string(),
 66→        value: "skip".to_string(),
 67→    });
 68→
 69→    options.push(PromptOption {
 70→        label: "Shell".to_string(),
 71→        value: "shell".to_string(),
 72→    });
 73→
 74→    options.push(PromptOption {
 75→        label: "Abort".to_string(),
 76→        value: "abort".to_string(),
 77→    });
 78→
 79→    let prompt = Prompt {
 80→        key: format!("recovery_{}", step_name),
 81→        question: "How do you want to proceed?".to_string(),
 82→        prompt_type: PromptType::Select { options },
 83→        default: Some("retry".to_string()),
 84→    };
 85→
 86→    let answer = ui.prompt(&prompt)?;
 87→    let value = answer.as_string();
 88→
 89→    match value.as_str() {
 90→        "retry" => Ok(RecoveryAction::Retry),
 91→        "fix" => {
 92→            if let Some(f) = fix {
 93→                Ok(RecoveryAction::Fix(f.command.clone()))
 94→            } else {
 95→                Ok(RecoveryAction::Retry)
 96→            }
 97→        }
 98→        "custom_fix" => {
 99→            let input_prompt = Prompt {
100→                key: format!("custom_fix_{}", step_name),
101→                question: "Enter fix command:".to_string(),
102→                prompt_type: PromptType::Input,
103→                default: None,
104→            };
105→            let input = ui.prompt(&input_prompt)?;
106→            let cmd = input.as_string();
107→            if cmd.trim().is_empty() {
108→                // User entered nothing, treat as retry
109→                Ok(RecoveryAction::Retry)
110→            } else {
111→                Ok(RecoveryAction::CustomFix(cmd))
112→            }
113→        }
114→        "skip" => Ok(RecoveryAction::Skip),
115→        "shell" => Ok(RecoveryAction::Shell),
116→        "abort" => Ok(RecoveryAction::Abort),
117→        _ => Ok(RecoveryAction::Retry),
118→    }
119→}
120→
121→/// Ask user to confirm running a fix command before executing it.
122→pub fn confirm_fix(ui: &mut dyn UserInterface, step_name: &str, command: &str) -> Result<bool> {
123→    let prompt = Prompt {
124→        key: format!("confirm_fix_{}", step_name),
125→        question: format!("Run `{}`?", command),
126→        prompt_type: PromptType::Confirm,
127→        default: Some("yes".to_string()),
128→    };
129→
130→    let answer = ui.prompt(&prompt)?;
131→    Ok(answer.as_bool().unwrap_or(true))
132→}
133→
134→/// Execute a fix command with the step's environment and working directory.
135→pub fn run_fix(command: &str, project_root: &Path, env: &HashMap<String, String>) -> Result<bool> {
136→    let options = CommandOptions {
137→        cwd: Some(project_root.to_path_buf()),
138→        env: env.clone(),
139→        capture_stdout: false,
140→        capture_stderr: false,
141→        ..Default::default()
142→    };
143→
144→    let result = execute(command, &options)?;
145→    Ok(result.success)
146→}
