 1→//! Contextual hint generation for Bivvy commands.
 2→//!
 3→//! Provides smart hint text that suggests the logical next action
 4→//! based on the current state of the project and command results.
 5→
 6→/// Generate a hint after a successful run.
 7→pub fn after_successful_run() -> &'static str {
 8→    "Run `bivvy status` to verify setup health."
 9→}
10→
11→/// Generate a hint after a failed run with specific failed steps.
12→pub fn after_failed_run(failed_steps: &[String]) -> String {
13→    if failed_steps.is_empty() {
14→        return "Run `bivvy run` to retry.".to_string();
15→    }
16→    format!(
17→        "Fix and re-run: `bivvy run --only={}`",
18→        failed_steps.join(",")
19→    )
20→}
21→
22→/// Generate a hint when all steps are pending (never run).
23→pub fn all_steps_pending() -> &'static str {
24→    "Run `bivvy run` to start setup."
25→}
26→
27→/// Generate a hint when some steps are pending.
28→pub fn some_steps_pending(pending: &[String]) -> String {
29→    format!(
30→        "Run `bivvy run --only={}` to run remaining steps.",
31→        pending.join(",")
32→    )
33→}
34→
35→/// Generate a hint after init when the user declines to run.
36→pub fn after_init() -> &'static str {
37→    "Run `bivvy run` when you're ready to start setup."
38→}
39→
