    // - Non-interactive verbose: print all output directly to stdout
    let output_mode = ui.output_mode();
    let output_callback = spinner
        .progress_bar()
        .and_then(|bar| {
            let max_lines = match output_mode {
                OutputMode::Verbose => 3,
                OutputMode::Normal => 2,
                _ => return None,
            };
            Some(live_output_callback(
                bar,
                attempt_label.clone(),
                6,
                max_lines,
