        let temp = TempDir::new().unwrap();

        let config: BivvyConfig = serde_yaml::from_str(
            r#"
            workflows:
              default:
                steps: [first, second]
        "#,
        )
        .unwrap();

        let mut steps = HashMap::new();
        steps.insert(
            "first".to_string(),
            make_step("first", "echo first", vec![]),
